import com.rs2.cache.js5.*; import com.rs2.model.music.*; import com.rs2.net.packet.*; import java.io.*;
public class InspectMusic2 { public static void main(String[] a)throws Exception{Interfaces.load();MusicTrackDefinition.loadDefinitions();try(Js5CacheStore s=new Js5CacheStore(new File("cache"))){Js5ReferenceTable t=s.readReferenceTable(6); for(Interfaces.Component c:Interfaces.group(239).values()){if(c.type!=4||c.actionType!=1)continue;ConfigReader r=new ConfigReader(c.getData());r.skip(17);int n=r.readUnsignedByte();int cond=-1,val=-1,config=-1,bit=-1;for(int j=0;j<n;j++){cond=r.readUnsignedByte();val=r.readUnsignedShort();}int ns=r.readUnsignedByte();for(int j=0;j<ns;j++){int len=r.readUnsignedShort();int op=r.readUnsignedShort();if(op==13){config=r.readUnsignedShort();bit=r.readUnsignedShort();r.skip((len-3)*2);}else{int vb=r.readUnsignedShort();r.skip((len-2)*2);System.out.println("VARBIT child="+c.childId+" id="+vb);}}r.skip(6);String name=r.readString();r.readString();int color=r.readInt();int id=-1;for(int k=0;k<MusicTrackDefinition.trackCount;k++)if(name.equalsIgnoreCase(MusicTrackDefinition.forTrackId(k).getName())){id=k;break;}MusicTrackDefinition old=MusicTrackDefinition.forTrackId(id);int asset=t.getGroupId(name);if(id>=0&&(config!=old.getUnlockConfigId()||(config>=0&&(1<<bit)!=old.getUnlockBitMask())))System.out.println("MISMATCH "+name+" native="+config+":"+bit+" legacy="+old.getUnlockConfigId()+":"+old.getUnlockBitMask());if(asset<0&&(id<0||AudioIds443.track(id)<0))System.out.println("NO ASSET "+c.childId+" "+name+" legacy="+id);if(id<0||n==0)System.out.println("NATIVE "+c.childId+" "+name+" "+config+":"+bit+" cond="+cond+":"+val+" color="+color+" asset="+asset);}}}}


